#include <bits/stdc++.h>
using namespace std;
#define ll long long 
#define all(x) (x).begin(),(x).end()

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    int t;
    cin >> t;
    while(t--){
        int x,a,b;
        cin >> x >> a >> b;
        int ans=0;
        if(x<80){
            ans+=a*(80-x);
            ans+=20*b;
        }
        else{
            ans=(100-x)*b;
        }
        cout << ans << "\n";
    }
}
